import { z } from 'zod';
export const PACKAGE_SCOPE_REGEX = /^@[a-z0-9-~][a-z0-9-._~]*$/;
export const packageIsolationModes = ['page', 'frame'];
const registryScopeSchema = z
    .string()
    .regex(PACKAGE_SCOPE_REGEX, 'Registry keys must be npm scopes such as `@acme` (lowercase, starting with `@`)');
const WHITESPACE_OR_CONTROL_REGEX = /[\s\u0000-\u001f\u007f]/;
const MAX_REGISTRY_URL_LENGTH = 512;
const registryUrlProblem = (value) => {
    if (WHITESPACE_OR_CONTROL_REGEX.test(value))
        return 'Registry URLs cannot contain whitespace';
    if (value.includes('${')) {
        return 'Registry URLs cannot contain `${`, which npm expands from environment variables';
    }
    if (/[;#\\]/.test(value)) {
        return 'Registry URLs cannot contain `;`, `#` or `\\`, which npm reads as a comment or escape in .npmrc';
    }
    let url;
    try {
        url = new URL(value);
    }
    catch (_a) {
        return undefined;
    }
    if (url.username !== '' || url.password !== '') {
        return 'Registry URLs cannot include a username, password or token';
    }
    if (value.includes('?') || url.hash !== '') {
        return 'Registry URLs cannot include a query string or fragment';
    }
    if (url.href.includes('${') || /[;#\\]/.test(url.href)) {
        return 'Registry URLs cannot parse to a URL with `${`, `;`, `#` or `\\`, such as from full-width characters in the host, which npm rewrites in .npmrc';
    }
    if (url.hostname.includes('=') || url.pathname.includes('=')) {
        return 'Registry URLs cannot have `=` in the host or path, which npm reads as the end of the auth token key in .npmrc';
    }
    return undefined;
};
const registryUrlSchema = z
    .string()
    .max(MAX_REGISTRY_URL_LENGTH, `Registry URLs cannot be longer than ${MAX_REGISTRY_URL_LENGTH} characters`)
    .url('Must be a valid URL')
    .regex(/^https:\/\/[^/]/, 'Registry URLs must start with `https://` and then the host')
    .superRefine((value, ctx) => {
    const message = registryUrlProblem(value);
    if (message)
        ctx.addIssue({ code: z.ZodIssueCode.custom, message });
});
const URL_SCHEME_REGEX = /^[a-z][a-z\d+.-]*:/i;
const isPackageCssPath = (value) => !/^[./\\]/.test(value) && !URL_SCHEME_REGEX.test(value) && !value.split(/[\\/]/).includes('..');
const cssEntrySchema = z
    .string()
    .min(1, 'CSS entries cannot be empty')
    .refine(isPackageCssPath, 'CSS entries must be paths inside an installed package, such as `@acme/ui/dist/styles.css`');
const providerPathProblem = (value) => {
    if (value === '')
        return undefined;
    const path = value.replace(/\\/g, '/');
    const segments = path.replace(/^\/+/, '').split('/');
    if (segments.includes('..'))
        return 'Provider path cannot contain `..` segments';
    if (segments.includes('')) {
        return 'Provider path must name a file, such as `/snippets/provider.jsx`, with no empty segments or trailing slash';
    }
    const stripped = path.replace(/[?#].*$/, '');
    const strippedRel = stripped.replace(/^\/+|\/+$/g, '');
    const searched = strippedRel === '' || strippedRel.split('/').includes('..') ? path : stripped;
    if (searched.split('/').slice(0, -1).includes('node_modules')) {
        return 'Provider path cannot be inside a `node_modules` folder';
    }
    if (!value.startsWith('/')) {
        return 'Provider path must start with `/`, such as `/snippets/provider.jsx`';
    }
    if (segments.some((seg) => /[:\0]/.test(seg) || (seg !== '.' && /[. ]$/.test(seg)))) {
        return 'Provider path cannot contain `:` or NUL, or a name that ends in `.` or a space';
    }
    return undefined;
};
const providerPathSchema = z
    .string()
    .min(1, 'Provider path cannot be empty')
    .superRefine((value, ctx) => {
    const message = providerPathProblem(value);
    if (message)
        ctx.addIssue({ code: z.ZodIssueCode.custom, message });
});
export const packagesSchema = z
    .object({
    registries: z
        .record(registryScopeSchema, registryUrlSchema)
        .optional()
        .describe('Registry to install each npm scope from, e.g. `{ "@acme": "https://npm.acme.com/" }`. One registry per scope. Unscoped packages always install from registry.npmjs.org.'),
    css: z
        .array(cssEntrySchema)
        .optional()
        .describe('Compiled CSS files shipped by your packages to load on pages that use package components, e.g. `@acme/ui/dist/styles.css`'),
    provider: providerPathSchema
        .optional()
        .describe('Path to a snippet that exports a `Provider` component, e.g. `/snippets/provider.jsx`. It wraps every package component.'),
    ssr: z
        .boolean()
        .optional()
        .describe('Whether to render package components to HTML at build time so they show before their JavaScript loads. Defaults to true.'),
    isolation: z
        .enum(packageIsolationModes)
        .optional()
        .describe('How package components run in the browser. `page` (default) renders them in the docs page. `frame`, a sandboxed iframe per component, is not implemented yet and fails the build.'),
})
    .describe('Use npm packages from package.json in MDX pages and snippets. Adding this key, even as `{}`, turns the feature on. Requires a package-lock.json or pnpm-lock.yaml next to docs.json.');
